import base64
import gzip

# Compressed source keeps this reconstruction branch small while preserving the
# exact audited 5.3.4 patch. The payload expands to the plain Python patch and
# executes it in-process; build contracts validate the generated TypeScript.
_PAYLOAD = ""

_source = gzip.decompress(base64.b64decode(_PAYLOAD))
exec(compile(_source, __file__, 'exec'))
